.cart-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: $ctl-h;
  padding: 0 $space-5;
  background: $blue-600;
  color: #fff;
  border: none;
  border-radius: $radius-full;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base;
  margin: $space-1 0;
  &:hover { background: $blue-700; }

  &__badge {
    background: $blue-700;
    color: #fff;
    border: 1px solid #fff;
    border-radius: $radius-full;
    font-size: $font-size-xs;
    font-weight: 700;
    padding: 0 6px;
    min-width: 20px;
    text-align: center;
    line-height: 18px;
  }
}

// ── Logout button (neutral secondary) ──────────────────────
.logout-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: $ctl-h;
  padding: 0 $space-4;
  background: $surface;
  color: $ink;
  border: 1px solid $line;
  border-radius: $radius-md;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, color $transition-base, border-color $transition-base;
  white-space: nowrap;

  &:hover { color: $danger; border-color: $danger; background: $danger-bg; }
