.cart-badge-mobile {
  position: absolute;
  top: -6px; right: -10px;
  background: $danger;
  color: #fff;
  border-radius: $radius-full;
  font-size: 11px;
  font-weight: 700;
  min-width: 18px; height: 18px;
  padding: 0 4px;
  display: flex; align-items: center; justify-content: center;
}

// ── Card grid ──────────────────────────────────────────────
.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: $space-4;

