    align-items: center; justify-content: center;
    gap: 3px; border: none; background: none;
    cursor: pointer; color: $ink-2;
    font-size: $font-size-xs; font-weight: $font-weight-medium;
    transition: color $transition-base;
    padding: 0;
    min-height: $bottom-nav-h;

    &--active {
      color: $blue-700;
      box-shadow: inset 0 3px 0 $blue-600;
    }

    &:hover { color: $blue-700; }
    &:focus-visible { box-shadow: inset $focus-ring; }
  }

  &__icon { font-size: 1.3rem; position: relative; }
  &__label { font-size: $font-size-xs; font-weight: $font-weight-semibold; }
