// ── Cart button in tab bar ─────────────────────────────────
.cart-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: $ctl-h;
  padding: 0 $space-5;
  background: $blue-600;
  color: #fff;
  border: none;
  border-radius: $radius-full;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base;
  margin: $space-1 0;
  &:hover { background: $blue-700; }

  &__badge {
    background: $blue-700;
    color: #fff;
    border: 1px solid #fff;
    border-radius: $radius-full;
    font-size: $font-size-xs;
    font-weight: 700;
    padding: 0 6px;
    min-width: 20px;
    text-align: center;
    line-height: 18px;
  }
}

// ── Logout button (neutral secondary) ──────────────────────
.logout-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: $ctl-h;
  padding: 0 $space-4;
  background: $surface;
  color: $ink;
  border: 1px solid $line;
  border-radius: $radius-md;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, color $transition-base, border-color $transition-base;
  white-space: nowrap;

  &:hover { color: $danger; border-color: $danger; background: $danger-bg; }
}

.cart-badge-mobile {
  position: absolute;
  top: -6px; right: -10px;
  background: $danger;
  color: #fff;
  border-radius: $radius-full;
  font-size: 11px;
  font-weight: 700;
  min-width: 18px; height: 18px;
  padding: 0 4px;
  display: flex; align-items: center; justify-content: center;
}

// ── Card grid ──────────────────────────────────────────────
.card-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: $space-4;

  @media (min-width: 520px)  { grid-template-columns: repeat(2, 1fr); }
  @media (min-width: 768px)  { gap: $space-5; }
  @media (min-width: 1024px) { grid-template-columns: repeat(3, 1fr); }
  @media (min-width: 1280px) { grid-template-columns: repeat(4, 1fr); }
}

// ── Token card ─────────────────────────────────────────────
.token-card {
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-lg;
  box-shadow: $shadow-card;
  overflow: hidden;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  min-width: 0;
  transition: border-color $transition-base, box-shadow $transition-base;

  &:hover {
    border-color: $blue-600;
    box-shadow: $shadow-pop;
  }

  &--buyable { box-shadow: inset 0 3px 0 $blue-600, $shadow-card; }

  &__image {
    height: 160px;
    background: $page;
    display: flex; align-items: center; justify-content: center;
    overflow: hidden;
    img { width: 100%; height: 100%; object-fit: cover; }
  }

  &__image-placeholder { font-size: 3rem; color: $ink-2; }

  &__header {
    display: flex; align-items: center; justify-content: space-between;
    gap: $space-2;
    padding: $space-3 $space-4 $space-1;
  }

  &__company {
    font-size: $font-size-xs; font-weight: 700;
    color: $blue-700; text-transform: uppercase; letter-spacing: 0.06em;
    min-width: 0; overflow-wrap: anywhere;
  }

  &__product {
    padding: 0 $space-4 $space-2;
    font-size: $font-size-md; font-weight: $font-weight-semibold; color: $ink; line-height: 1.3;
    overflow-wrap: anywhere;
  }

  &__body {
    display: flex; flex-wrap: wrap; gap: $space-4 $space-2;
    padding: $space-1 $space-4 $space-4;
    flex: 1;
  }

  &__stat {
    display: flex; flex-direction: column; gap: 2px;
    font-size: $font-size-base; color: $ink;
    min-width: 60px;
    font-variant-numeric: tabular-nums;
  }

  &__stat-row {
    display: flex; flex-basis: 100%; width: 100%;
    gap: $space-4;
    > .token-card__stat { flex: 1; min-width: 0; }
  }

  &__stat--full { flex-basis: 100%; width: 100%; }

  &__stat-label {
    font-size: $font-size-xs; color: $ink-2;
    font-weight: $font-weight-semibold; text-transform: uppercase; letter-spacing: 0.04em;
  }

  &__stat-value { font-weight: $font-weight-medium; }
  &__price { color: $ink; font-weight: 700; font-variant-numeric: tabular-nums; }
  &__mono  { font-family: $font-family-mono; font-size: $font-size-xs; }

  &__footer {
    display: flex; align-items: center; justify-content: space-between;
    flex-wrap: wrap; gap: $space-2;
    padding: $space-3 $space-4;
    border-top: 1px solid $line;
  }

  &__id { font-size: $font-size-xs; color: $ink-2; font-family: $font-family-mono; }

  &__actions { display: flex; gap: $space-2; flex-wrap: wrap; margin-left: auto; }
}

// ── Small action buttons on cards ─────────────────────────
.tc-btn {
  min-height: $ctl-h;
  padding: $space-2 $space-4;
  border-radius: $radius-md;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background $transition-base, opacity $transition-base, border-color $transition-base;

  &--sm { padding: $space-2 $space-3; font-size: $font-size-sm; }

  &--green { background: $blue-600; color: #fff; &:hover { background: $blue-700; } }
  &--outline {
    background: $surface; color: $blue-700;
    border-color: $blue-600;
    &:hover:not(:disabled) { background: $blue-50; }
  }
  &--in-cart { background: $blue-50; color: $blue-700; border-color: $blue-50; }
  &--warn { background: $warn-bg; color: $warn; border-color: $warn; &:hover { background: #fde6c4; } }
  &--ghost { background: $surface; color: $ink; border-color: $line; &:hover { background: $page; } }

  &:disabled { opacity: 0.55; cursor: not-allowed; }
}

// ── Modal backdrop & modal ─────────────────────────────────
.modal-backdrop {
  position: fixed; inset: 0;
  background: rgba($ink, 0.5);
  display: flex; align-items: center; justify-content: center;
  z-index: $z-modal-backdrop;
  padding: $space-4;
  overflow-y: auto;
}

.modal {
  background: $surface;
  border-radius: $radius-xl;
  width: 100%; max-width: 520px;
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  position: relative;
  z-index: $z-modal;
  box-shadow: $shadow-pop;

  &__close {
    position: absolute; top: $space-3; right: $space-3;
    width: $ctl-h; height: $ctl-h;
    background: $surface; border: 1px solid $line; border-radius: 50%;
    font-size: 1.4rem; line-height: 1; cursor: pointer; color: $ink;
    display: flex; align-items: center; justify-content: center;
    &:hover { background: $page; }
  }

  &__image {
    height: 220px; background: $page;
    display: flex; align-items: center; justify-content: center;
    overflow: hidden; border-radius: $radius-xl $radius-xl 0 0;
    img { width: 100%; height: 100%; object-fit: cover; }
  }

  &__image-placeholder { font-size: 4rem; color: $ink-2; }

  &__body { padding: $space-4; @include sm { padding: $space-5 $space-6 $space-6; } }

  &__company-row {
    display: flex; align-items: center; justify-content: space-between;
    gap: $space-2; margin-bottom: $space-1;
  }

  &__company {
    font-size: $font-size-xs; font-weight: 700;
    color: $blue-700; text-transform: uppercase; letter-spacing: 0.06em;
  }

  &__product {
    font-size: 1.25rem; font-weight: 700; color: $ink;
    margin: 0 0 $space-4; line-height: 1.25; overflow-wrap: anywhere;
  }

  &__details {
    display: grid; grid-template-columns: 1fr;
    gap: $space-4; margin: 0 0 $space-6;
    @include sm { grid-template-columns: 1fr 1fr; }
    dt { font-size: $font-size-xs; color: $ink-2; text-transform: uppercase; font-weight: 700; letter-spacing: 0.04em; margin-bottom: $space-1; }
    dd { font-size: $font-size-base; color: $ink; font-weight: 500; margin: 0; font-variant-numeric: tabular-nums; }
    > div.full-span { @include sm { grid-column: 1 / -1; } }
  }

  &__price { font-size: 1.25rem; font-weight: 700; color: $ink; }

  &__actions {
    display: flex; flex-direction: column; gap: $space-2;
    .tc-btn { width: 100%; }
    @include sm {
      flex-direction: row; flex-wrap: wrap;
      .tc-btn { width: auto; }
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .spinning, .loading-bar, .tab-content { animation: none; }
}

tool_use_result.content:
@use '../../../../styles/variables' as *;
@use '../../../../styles/mixins' as *;

$bottom-nav-h: 64px;
$app-bar-h:    56px;

// ── Host ──────────────────────────────────────────────────────
:host {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background: $page;
  font-family: $font-family-base;
  color: $ink;
}

button, select { font-family: inherit; }
button:focus-visible,
select:focus-visible { outline: none; box-shadow: $focus-ring; }

// ── App bar ───────────────────────────────────────────────────
.app-bar {
  position: sticky;
  top: 0;
  z-index: $z-sticky;
  background: $surface;
  border-bottom: 1px solid $line;
  box-shadow: $shadow-card;

  &__inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: $space-3;
    padding: 0 $container-padding-mobile;
    min-height: $app-bar-h;
    @include md { padding: 0 $container-padding; }
  }

  &__brand { display: flex; align-items: center; gap: $space-2; min-width: 0; }
  &__logo  { font-size: 1.4rem; color: $blue-600; }
  &__title { font-size: $font-size-lg; font-weight: $font-weight-bold; color: $ink; }

  &__meta { display: flex; align-items: center; gap: $space-2; min-width: 0; }

  &__key {
    font-size: $font-size-xs;
    font-family: $font-family-mono;
    color: $ink-2;
    background: $page;
    border: 1px solid $line;
    padding: 4px $space-3;
    border-radius: $radius-full;
    @include truncate;
    max-width: 140px;
  }

  &__refresh {
    width: $ctl-h; height: $ctl-h;
    background: none; border: none; cursor: pointer;
    font-size: 1.2rem; color: $blue-600;
    border-radius: $radius-full;
    display: flex; align-items: center; justify-content: center;
    transition: background $transition-base;
    &:hover { background: $blue-50; }
    &:disabled { opacity: 0.55; cursor: not-allowed; }
  }
}

@keyframes spin { to { transform: rotate(360deg); } }
.spinning { display: inline-block; animation: spin 0.8s linear infinite; }

// ── Filter bar (desktop) ──────────────────────────────────────
.filter-bar {
  display: flex;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: $space-3;
  padding: $space-3 $container-padding-mobile;
  border-top: 1px solid $line;
  background: $surface;

  @include md { padding: $space-3 $container-padding; }

  &__field {
    display: flex; flex-direction: column; gap: $space-1;
    flex: 1 1 100%;
    @include sm { flex: 0 1 auto; }
  }

  &__label {
    font-size: $font-size-xs; font-weight: $font-weight-semibold;
    color: $ink-2; text-transform: uppercase; letter-spacing: 0.04em;
  }

  &__input {
    min-height: $ctl-h;
    padding: $space-2 $space-3;
    border: 1px solid $line; border-radius: $radius-md;
    font-size: $font-size-md; color: $ink;
    background: $surface; width: 100%;
    @include sm { min-width: 160px; width: auto; font-size: $font-size-base; }
    &:focus { outline: none; border-color: $blue-600; box-shadow: $focus-ring; }
    &:disabled {
      background: $page;
      color: $ink-2;
      cursor: not-allowed;
      opacity: 0.55;
    }
  }

  &__btn {
    min-height: $ctl-h;
    padding: $space-2 $space-4;
    border-radius: $radius-md; font-size: $font-size-base;
    font-weight: $font-weight-semibold; cursor: pointer;
    border: 1px solid $line; background: $surface; color: $ink;
    transition: background $transition-base, border-color $transition-base;
    align-self: flex-end;
    flex: 1 1 calc(50% - #{$space-2});
    @include sm { flex: 0 0 auto; }
    &:hover { background: $page; border-color: $ink-2; }
    &--primary { background: $blue-600; color: #fff; border-color: $blue-600;
      &:hover { background: $blue-700; border-color: $blue-700; } }
  }
}

// ── Desktop tab bar (hidden on mobile) ───────────────────────
.desktop-tabs {
  display: none;
  align-items: flex-end;
  border-top: 1px solid $line;
  padding: 0 $container-padding;
  background: $surface;
  overflow-x: auto;

  @include md { display: flex; gap: 0; }

  &__spacer { flex: 1; }
}

.desktop-tab {
  min-height: $ctl-h;
  padding: $space-3 $space-5;
  background: none;
  border: none;
  border-bottom: 3px solid transparent;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  color: $ink-2;
  cursor: pointer;
  transition: color $transition-base, border-color $transition-base;
  white-space: nowrap;

  &:hover { color: $blue-700; }

  &--active {
    color: $blue-700;
    border-bottom-color: $blue-600;
  }
}

// ── Loading bar ───────────────────────────────────────────────
.loading-bar {
  height: 3px;
  background: $blue-600;
  animation: loading 1.2s ease infinite;
}
@keyframes loading {
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

// ── Main content ──────────────────────────────────────────────
.main-content {
  flex: 1;
  width: 100%;
  max-width: calc(#{$container-max-width} + 2 * #{$container-padding});
  margin: 0 auto;
  padding: $space-4 $container-padding-mobile;
  padding-bottom: calc(#{$bottom-nav-h} + #{$space-4} + env(safe-area-inset-bottom, 0px));

  @include md { padding: $space-4 $container-padding; }
}

.tab-content { animation: fade-in 0.15s ease; }
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

// ── Badges ────────────────────────────────────────────────────
.badge {
  display: inline-flex; align-items: center;
