// ── Pay panel ────────────────────────────────────────────
.pay-panel {
  display: grid;
  gap: 12px;
  justify-items: center;

  &__secure {
    margin: 0;
    font-size: 0.8rem;
    color: $text-muted;
    text-align: center;
    max-width: 420px;
  }

  &__loading { display: inline-flex; align-items: center; gap: 8px; }
}

// ── Buttons ──────────────────────────────────────────────
.btn {
  border: none;
  border-radius: $radius-full;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.15s, box-shadow 0.15s;

  &:disabled { opacity: 0.55; cursor: not-allowed; }

  &--primary {
    padding: 10px 24px;
    background: $primary;
    color: #fff;
    &:hover:not(:disabled) { background: $primary-dark; }
  }

  &--pay {
    width: 100%;
    max-width: 420px;
    padding: 15px 24px;
    font-size: 1rem;
    background: $primary;
    color: #fff;
    box-shadow: 0 4px 14px rgba(5, 150, 105, 0.35);
