  }

  &--ghost {
    padding: 10px 22px;
    background: transparent;
    color: $primary;
    border: 1px solid $primary-muted;
    &:hover:not(:disabled) { background: $primary-bg; }
  }
}

// ── Spinner ──────────────────────────────────────────────
.spinner {
  width: 28px;
  height: 28px;
  border: 3px solid $primary-muted;
  border-top-color: $primary;
  border-radius: 50%;
  margin: 0 auto 14px;
  animation: spin 0.8s linear infinite;

  &--sm { width: 16px; height: 16px; border-width: 2px; margin: 0; }
}

@keyframes spin { to { transform: rotate(360deg); } }

// ── Embedded Flitt widget ────────────────────────────────
.embedded {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;

  &__progress {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    margin-bottom: 16px;
    text-align: center;
  }

  &__product { font-weight: 700; font-size: 1.05rem; }
  &__company { font-size: 0.85rem; color: $text-muted; }
