    margin-top: 6px;
    font-size: 0.72rem;
    font-weight: 700;
    color: $primary;
    background: $primary-muted;
    border-radius: $radius-full;
    padding: 3px 12px;
  }

  &__widget {
    min-height: 360px;
    background: $surface;
    border: 1px solid $border;
    border-radius: $radius-xl;
    box-shadow: 0 8px 28px rgba(0, 0, 0, 0.08);
    padding: 12px;
    overflow: hidden;
