  border: 1px solid $border;
  border-radius: $radius-xl;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.10);
  padding: 40px 32px;
  text-align: center;

  h1 { margin: 8px 0 6px; font-size: 1.25rem; }
  p  { margin: 0 0 6px; color: $text-muted; }
