@use '../../../../styles/mixins' as *;

$action-bar-h: 80px;

:host {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background: $page;
  font-family: $font-family-base;
  color: $ink;
}

button { font-family: inherit; }
button:focus-visible { outline: none; box-shadow: $focus-ring; }

// ── Header ────────────────────────────────────────────────────
.detail-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: $space-2 $space-3;
  padding: $space-2 $space-4;
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-lg;
  box-shadow: $shadow-card;

  &__title {
    flex: 1 1 auto;
    font-size: $font-size-lg;
    font-weight: $font-weight-bold;
    color: $ink;
    margin: 0;
    overflow-wrap: anywhere;
  }
}

.back-btn {
  display: flex; align-items: center; gap: 4px;
  min-height: $ctl-h;
  background: none; border: none; cursor: pointer;
  color: $blue-600; font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  padding: 0 $space-3;
  border-radius: $radius-md;
  transition: background $transition-base;
  &:hover { background: $blue-50; }
  &__icon { font-size: 1.4rem; line-height: 1; }
}

// ── Logout button (neutral secondary) ──────────────────────────
.logout-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: $ctl-h;
  padding: 0 $space-4;
  background: $surface;
  color: $ink;
  border: 1px solid $line;
  border-radius: $radius-md;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, color $transition-base, border-color $transition-base;
  white-space: nowrap;

  &:hover { color: $danger; border-color: $danger; background: $danger-bg; }
}

// ── Sections ──────────────────────────────────────────────────
.detail-page {
  flex: 1;
  padding: $space-4 $container-padding-mobile;
  padding-bottom: calc(#{$action-bar-h} + #{$space-4} + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: $space-3;
  max-width: 720px;
  width: 100%;
  margin: 0 auto;

  @include md { padding: $space-6 $container-padding; padding-bottom: calc(#{$action-bar-h} + #{$space-6}); gap: $space-4; }
}

.detail-section {
  background: $surface;
  border: 1px solid $line;
  border-radius: $radius-lg;
  box-shadow: $shadow-card;
  overflow: hidden;

  &__title {
    font-size: $font-size-xs;
    font-weight: $font-weight-semibold;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: $ink-2;
    padding: $space-3 $space-4;
    background: $page;
    border-bottom: 1px solid $line;
    margin: 0;
  }

  &--muted { background: $page; }
}

.detail-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: $space-3 $space-4;
  border-bottom: 1px solid $line;
  gap: $space-4;

  &:last-child { border-bottom: none; }

  &__label {
    font-size: $font-size-base;
    color: $ink-2;
    flex-shrink: 1;
    min-width: 0;
  }

  &__value {
    font-size: $font-size-base;
    font-weight: $font-weight-medium;
    color: $ink;
    text-align: right;
    word-break: break-all;
    font-variant-numeric: tabular-nums;
    min-width: 0;

    &.mono { font-family: $font-family-mono; font-size: $font-size-xs; }
    &.small { font-size: $font-size-xs; }
  }
}

// ── Badges ────────────────────────────────────────────────────
.badge {
  display: inline-flex; padding: 2px 10px;
  border-radius: $radius-full;
  font-size: $font-size-xs; font-weight: $font-weight-semibold;
  white-space: nowrap;
  &--green  { background: $ok-bg; color: $ok; }
  &--blue   { background: $blue-50; color: $blue-700; }
  &--yellow { background: $warn-bg; color: $warn; }
  &--gray   { background: $page; color: $ink-2; border: 1px solid $line; }
}

.mono { font-family: $font-family-mono; font-size: $font-size-xs; }

// ── Action bar ────────────────────────────────────────────────
.action-bar {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  display: flex;
  flex-direction: column-reverse;
  gap: $space-2;
  padding: $space-3 $space-4;
  padding-bottom: calc(#{$space-3} + env(safe-area-inset-bottom, 0px));
  background: $surface;
  border-top: 1px solid $line;
  z-index: $z-sticky;

  @include sm { flex-direction: row; justify-content: center; }

  &__btn {
    flex: 1;
    min-height: 48px;
    padding: $space-3;
    border-radius: $radius-md;
    font-size: $font-size-base;
    font-weight: $font-weight-semibold;
    cursor: pointer; border: 1px solid transparent;
    transition: background $transition-base, border-color $transition-base;
    display: flex; align-items: center; justify-content: center; gap: $space-2;

    @include sm { max-width: 240px; }

    &--primary {
      background: $blue-600; color: #fff;
      &:hover:not(:disabled) { background: $blue-700; }
    }
    &--warn {
      background: $warn-bg; color: $warn; border-color: $warn;
      &:hover:not(:disabled) { background: #fde6c4; }
    }
    &--ghost {
      background: $surface; color: $ink; border-color: $line;
      &:hover { background: $page; }
    }
    &:disabled { opacity: 0.55; cursor: not-allowed; }
  }
}

// ── Spinner ───────────────────────────────────────────────────
.spinner {
  width: 16px; height: 16px;
  border: 2px solid rgba(255,255,255,0.4);
  border-top-color: #fff;
  border-radius: 50%;
