@use '../../../../styles/variables' as *;
@use '../../../../styles/mixins' as *;

$primary:      #059669;
$primary-dark: #047857;
$primary-bg:   #f0fdf4;
$border:       #6ee7b7;
$surface:      #ffffff;
$text:         #064e3b;
$text-muted:   #64748b;

:host {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-height: 100dvh; // dynamic viewport for mobile
  background: linear-gradient(160deg, $primary-bg 0%, #f8fafb 60%, #ecfdf5 100%);
  padding: $space-6 $space-4;
  padding-top: max(#{$space-10}, env(safe-area-inset-top, #{$space-10}));
  @include flex-center;
}

.auth-container {
  width: 100%;
  max-width: 400px;
  background: $surface;
  border: 1px solid $border;
  border-radius: $radius-xl;
  padding: $space-8 $space-6;
  box-shadow: 0 8px 32px rgba($primary, 0.08), 0 2px 8px rgba(0,0,0,0.04);

  // On very small screens, remove card padding
  @media (max-width: 360px) { padding: $space-6 $space-4; }

  h2 {
    text-align: center;
    font-size: $font-size-xl;
    font-weight: $font-weight-bold;
    color: $text;
    margin: 0 0 $space-6;
  }
}

// ── Tab toggle ────────────────────────────────────────────────
.toggle-btn {
  display: block;
  width: 100%;
  padding: $space-2 $space-4;
  margin-bottom: $space-6;
  background: #f0fdf4;
  border: 1px solid $border;
  border-radius: $radius-md;
  color: $text-muted;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  cursor: pointer;
  transition: all $transition-base;
  @include hover-lift;

  &:hover {
    background: rgba($primary, 0.1);
    border-color: $primary;
    color: $text;
  }
}

// ── Form ──────────────────────────────────────────────────────
.auth-form {
  display: flex; flex-direction: column; gap: $space-4;

  label {
    display: flex; flex-direction: column; gap: $space-2;
    font-size: $font-size-sm; font-weight: $font-weight-semibold;
    color: $text-muted; text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  input {
    padding: $space-3 $space-4;
    background: $surface;
    border: 1.5px solid #e5e7eb;
    border-radius: $radius-lg;
    color: $text;
    font-size: $font-size-md; // 16px — prevents iOS zoom
    font-family: $font-family-base;
    transition: border-color $transition-base, box-shadow $transition-base;
    -webkit-appearance: none;

    &:focus {
      outline: none;
      border-color: $primary;
      box-shadow: 0 0 0 3px rgba($primary, 0.12);
    }
  }

  button[type="submit"] {
    margin-top: $space-2;
    padding: $space-4;
    background: $primary;
    border: none; border-radius: $radius-lg;
    color: #fff;
    font-size: $font-size-base; font-weight: $font-weight-semibold;
    font-family: $font-family-base;
    cursor: pointer;
    min-height: 48px; // touch target
    transition: background $transition-base, box-shadow $transition-base;

    &:hover:not(:disabled) {
      background: $primary-dark;
      box-shadow: 0 4px 16px rgba($primary, 0.3);
    }
    &:disabled { opacity: 0.55; cursor: not-allowed; }
  }
}

// ── Error message ─────────────────────────────────────────────
.auth-error {
  padding: $space-3 $space-4;
  background: #fef2f2;
  border: 1px solid #fca5a5;
  border-radius: $radius-md;
  color: #b91c1c;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  text-align: center;
}

// ── Back link ─────────────────────────────────────────────────
.back-link {
  display: block;
  text-align: center;
  margin-top: $space-5;
  color: $primary;
  font-size: $font-size-sm;
  font-weight: $font-weight-medium;
  text-decoration: none;
  &:hover { text-decoration: underline; }
}

