}

.dialog {
  width: 100%;
  max-width: 400px;
  max-height: calc(100dvh - 32px);
  overflow-y: auto;
  background: $surface;
  border-radius: $radius-xl;
  box-shadow: $shadow-pop;
  padding: $space-4;
  text-align: center;
  z-index: $z-modal;

  @media (min-width: $breakpoint-sm) { padding: $space-6; }

  &__icon {
    width: 56px;
    height: 56px;
    margin: 0 auto $space-4;
    border-radius: $radius-full;
    display: flex;
    align-items: center;
    justify-content: center;

    svg { width: 28px; height: 28px; }
  }

  &--danger .dialog__icon  { background: $danger-bg; color: $danger; }
  &--warning .dialog__icon { background: $warn-bg; color: $warn; }
  &--info .dialog__icon    { background: $blue-50; color: $blue-700; }

  &__title {
    margin: 0 0 $space-2;
    font-size: $font-size-lg;
    font-weight: $font-weight-semibold;
    color: $ink;
  }

  &__message {
    margin: 0 0 $space-6;
    font-size: $font-size-base;
    color: $ink-2;
    line-height: $line-height-relaxed;
    overflow-wrap: anywhere;
  }

  // Primary action first on mobile (column-reverse keeps DOM order: cancel, confirm).
  &__actions {
    display: flex;
    flex-direction: column-reverse;
    gap: $space-2;

    .btn { width: 100%; }

    @media (min-width: 480px) {
      flex-direction: row;
      justify-content: center;
      gap: $space-3;
      .btn { flex: 1; width: auto; }
