  font-family: inherit;
  font-size: $font-size-base;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, border-color $transition-base;
  min-width: 100px;

  &:focus-visible { outline: none; box-shadow: $focus-ring; }
  &:disabled { opacity: 0.55; cursor: not-allowed; }

  &--secondary {
    background: $surface;
    color: $ink;
    border-color: $line;

    &:hover { background: $page; border-color: $ink-2; }
  }

  &--danger {
    background: $danger;
    color: #fff;
    &:hover { background: #991B1B; }
  }

  &--warning {
    background: $warn;
    color: #fff;
    &:hover { background: #78350F; }
  }

  &--info {
    background: $blue-600;
    color: #fff;
    &:hover { background: $blue-700; }
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop { animation: none; }
}

