1	import { Component, inject, HostListener, ViewChild, ElementRef, AfterViewChecked } from '@angular/core';
2	import { CommonModule } from '@angular/common';
3	import { DialogService } from '../../../core/services/dialog.service';
4	
5	@Component({
6	  selector: 'app-confirm-dialog',
7	  standalone: true,
8	  imports: [CommonModule],
9	  template: `
10	    @if (dialogService.state().open && dialogService.state().options; as opts) {
11	      <div class="dialog-backdrop" (click)="onBackdropClick($event)">
12	        <div
13	          #dialogEl
14	          class="dialog"
15	          [class]="'dialog--' + opts.type"
16	          role="alertdialog"
17	          aria-modal="true"
18	          [attr.aria-labelledby]="'dialog-title'"
19	          [attr.aria-describedby]="'dialog-message'"
20	          tabindex="-1"
21	          (keydown)="onKeydown($event)">
22	          <div class="dialog__icon" aria-hidden="true">
23	            @switch (opts.type) {
24	              @case ('danger') {
25	                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
26	                  <circle cx="12" cy="12" r="10"/>
27	                  <path d="M15 9l-6 6M9 9l6 6"/>
28	                </svg>
29	              }
30	              @case ('warning') {
31	                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
32	                  <path d="M12 9v4m0 4h.01"/>
33	                  <path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/>
34	                </svg>
35	              }
36	              @default {
37	                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
38	                  <circle cx="12" cy="12" r="10"/>
39	                  <path d="M12 16v-4m0-4h.01"/>
40	                </svg>
41	              }
42	            }
43	          </div>
44	          <h3 id="dialog-title" class="dialog__title">{{ opts.title }}</h3>
45	          <p id="dialog-message" class="dialog__message">{{ opts.message }}</p>
46	          <div class="dialog__actions">
47	            <button
48	              #cancelBtn
49	              class="btn btn--secondary"
50	              (click)="dialogService.close(false)">
51	              {{ opts.cancelText }}
52	            </button>
53	            <button
54	              #confirmBtn
55	              class="btn"
56	              [class]="'btn--' + opts.type"
57	              (click)="dialogService.close(true)">
58	              {{ opts.confirmText }}
59	            </button>
60	          </div>
61	        </div>
62	      </div>
63	    }
64	  `,
65	  styleUrl: './confirm-dialog.component.scss'
66	})
67	export class ConfirmDialogComponent implements AfterViewChecked {
68	  readonly dialogService = inject(DialogService);
69	
