file.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

// ── Reset & base ──────────────────────────────────────────────────────────────
:host {
  display: block;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: #111827;
  background: #fff;
  -webkit-font-smoothing: antialiased;
}

*, *::before, *::after { box-sizing: border-box; }

a { text-decoration: none; }

// ── Shared layout ─────────────────────────────────────────────────────────────
.section-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-title {
  font-size: clamp(1.6rem, 3vw, 2.25rem);
  font-weight: 800;
  color: #111827;
  text-align: center;
  margin: 0 0 12px;
  letter-spacing: -0.5px;
}

.section-subtitle {
  font-size: 1.05rem;
  color: #6b7280;
  text-align: center;
  margin: 0;
  line-height: 1.6;
}

// ── Buttons ───────────────────────────────────────────────────────────────────
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 10px;
  font-family: inherit;
  font-weight: 600;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  white-space: nowrap;
  min-height: 44px;
  padding: 12px 24px;
  font-size: 1rem;

  &:focus-visible { outline: 2px solid #059669; outline-offset: 3px; }

  &--primary {
    background: #059669;
    color: #fff;
    &:hover { background: #047857; transform: translateY(-1px); box-shadow: 0 4px 16px rgba(26,86,219,0.3); }
    &:active { transform: translateY(0); }
  }


  &--outline {
    background: transparent;
    color: #059669;
    border: 2px solid #059669;
    &:hover { background: #f0fdf4; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(5,150,105,0.15); }
    &:active { transform: translateY(0); }
  }
  &--lg { padding: 14px 32px; font-size: 1.05rem; border-radius: 12px; }

  &--full { width: 100%; }

  &:disabled { opacity: 0.65; cursor: not-allowed; transform: none !important; box-shadow: none !important; }
}

.btn__spinner {
  width: 16px; height: 16px;
  border: 2px solid rgba(255,255,255,0.4);
  border-top-color: #fff;
  border-radius: 50%;
  animation: spin 0.6s linear infinite;
}

@keyframes spin { to { transform: rotate(360deg); } }

// ── Navbar ────────────────────────────────────────────────────────────────────
.navbar {
  position: sticky;
  top: 0;
  z-index: 200;
  background: #fff;
  border-bottom: 1px solid #e5e7eb;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);

  &__inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
    height: 68px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
  }

  &__brand {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #059669;
    font-weight: 700;
    font-size: 1.2rem;
    letter-spacing: -0.5px;
    flex-shrink: 0;
  }

  &__logo-icon { font-size: 1.4rem; }
  &__auth {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
  }


  &__center {
    display: flex;
    align-items: center;
    gap: 28px;
    flex: 1;
    justify-content: center;

    @media (max-width: 767px) { display: none; }
  }

  &__link {
    color: #374151;
    font-size: 0.95rem;
    font-weight: 500;
    transition: color 0.2s;
    &:hover, &:focus-visible { color: #059669; }
  }
}

// ── PWA Banner ──────────────────────────────────────────────────────────────

// ── Hero ──────────────────────────────────────────────────────────────────────
.hero {
  background: linear-gradient(135deg, #f0fdf4 0%, #fff 60%);
  padding: 100px 0 80px;

  &__inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 64px;
    align-items: center;
  }

  &__headline {
    font-size: clamp(2rem, 4vw, 3.2rem);
    font-weight: 800;
    color: #111827;
    line-height: 1.2;
    margin: 0 0 20px;
    letter-spacing: -1px;
  }

  &__subheadline {
    font-size: 1.15rem;
    color: #4b5563;
    line-height: 1.7;
    margin: 0 0 40px;
  }

  &__actions {
    display: flex;
    align-items: center;
    gap: 28px;
    flex-wrap: wrap;
  }

  &__secondary-cta {
    color: #059669;
    font-weight: 600;
    font-size: 0.95rem;
    transition: opacity 0.2s;
    &:hover { opacity: 0.75; }
  }

  &__visual { display: flex; justify-content: center; }
}

.token-graphic {
  display: flex;
  align-items: center;
  gap: 16px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 20px;
  padding: 36px 40px;
  box-shadow: 0 8px 32px rgba(26,86,219,0.08);
}

.token {
  display: flex; flex-direction: column; align-items: center; gap: 10px; width: 90px;

  &__icon {
    width: 64px; height: 64px; border-radius: 50%;
    background: #ecfdf5;
    display: flex; align-items: center; justify-content: center;
    font-size: 1.6rem; color: #059669;
  }

  &__label { font-size: 0.85rem; font-weight: 600; color: #374151; text-align: center; }
  &--2 .token__icon { background: #d1fae5; }
  &--3 .token__icon { background: #d1fae5; color: #059669; }
}

.token-arrow { font-size: 1.5rem; color: #9ca3af; }

// ── How It Works ──────────────────────────────────────────────────────────────
.how-it-works { padding: 96px 0; background: #fff; }

.hiw {
  &__steps { display: flex; align-items: flex-start; margin-top: 56px; }
  &__step { flex: 1; text-align: center; padding: 0 24px; }
  &__step-number {
    width: 36px; height: 36px; border-radius: 50%;
    background: #059669; color: #fff;
    font-weight: 700; font-size: 0.9rem;
    display: inline-flex; align-items: center; justify-content: center; margin-bottom: 16px;
  }
  &__step-icon { font-size: 2.4rem; display: block; margin-bottom: 16px; }
  &__step-title { font-size: 1.15rem; font-weight: 700; color: #111827; margin: 0 0 10px; }
  &__step-desc { font-size: 0.95rem; color: #6b7280; line-height: 1.6; margin: 0; }
  &__connector {
    width: 80px; height: 2px;
    background: linear-gradient(90deg, #6ee7b7, #059669);
    margin-top: 60px; flex-shrink: 0;
  }
}

// ── Value Proposition ─────────────────────────────────────────────────────────
.value-prop { padding: 96px 0; background: #f9fafb; }

.vp {
  &__cards {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 56px;
  }
  &__card {
    background: #fff; border: 1px solid #e5e7eb; border-radius: 16px; padding: 32px 28px;
    transition: box-shadow 0.2s, transform 0.2s;
    &:hover { box-shadow: 0 8px 24px rgba(26,86,219,0.1); transform: translateY(-2px); }
  }
  &__card-icon { font-size: 2rem; margin-bottom: 16px; display: block; }
  &__card-title { font-size: 1.05rem; font-weight: 700; color: #111827; margin: 0 0 10px; }
  &__card-desc { font-size: 0.92rem; color: #6b7280; line-height: 1.6; margin: 0; }
}

// ── Trust ─────────────────────────────────────────────────────────────────────
.trust {
  padding: 96px 0; background: #fff; text-align: center;

  &__mission {
    max-width: 640px; margin: 0 auto 48px;
    font-size: 1.05rem; color: #4b5563; line-height: 1.75;
  }
  &__badges { display: flex; justify-content: center; gap: 20px; flex-wrap: wrap; margin-bottom: 0; }
  &__badge {
    display: flex; align-items: center; gap: 10px;
    background: #f0fdf4; border: 1px solid #6ee7b7; border-radius: 100px; padding: 10px 20px;
    &-icon { font-size: 1.1rem; }
    &-text { font-size: 0.875rem; font-weight: 500; color: #065f46; }
  }
}

// ── FAQ ───────────────────────────────────────────────────────────────────────
.faq {
  padding: 96px 0; background: #f9fafb;

  &__list { margin: 48px auto 0; max-width: 760px; }
  &__item {
    border: 1px solid #e5e7eb; border-radius: 12px; margin-bottom: 12px;
    background: #fff; overflow: hidden; transition: box-shadow 0.2s;
    &--open { box-shadow: 0 4px 16px rgba(26,86,219,0.08); border-color: #6ee7b7; }
  }
  &__btn {
    width: 100%; display: flex; justify-content: space-between; align-items: center;
    padding: 20px 24px; background: none; border: none; cursor: pointer;
    font-size: 1rem; font-weight: 600; color: #111827; text-align: left; gap: 16px;
    min-height: 44px; font-family: inherit;
    &:focus-visible { outline: 2px solid #059669; outline-offset: -2px; }
    &:hover { background: #f9fafb; }
  }
  &__chevron { font-size: 1.3rem; color: #059669; flex-shrink: 0; }
  &__answer { padding: 0 24px 20px; color: #4b5563; font-size: 0.95rem; line-height: 1.7; margin: 0; }
}

// ── Bottom CTA ────────────────────────────────────────────────────────────────
.bottom-cta {
  padding: 96px 0;
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  text-align: center;

  &__inner { display: flex; flex-direction: column; align-items: center; gap: 20px; }
  &__title { font-size: clamp(1.6rem, 3vw, 2.25rem); font-weight: 800; color: #fff; margin: 0; letter-spacing: -0.5px; }
  &__sub { font-size: 1.05rem; color: rgba(255,255,255,0.85); margin: 0; max-width: 480px; }
  &__btn { background: #fff; color: #059669; &:hover { background: #f0fdf4; box-shadow: 0 4px 20px rgba(0,0,0,0.15); } }
}

// ── Footer ────────────────────────────────────────────────────────────────────
.footer {
  background: #111827; padding: 48px 0 32px;

  &__inner {
    max-width: 1200px; margin: 0 auto; padding: 0 24px;
    display: flex; flex-direction: column; align-items: center; gap: 24px; text-align: center;
  }
  &__logo { display: inline-flex; align-items: center; gap: 8px; color: #fff; font-weight: 700; font-size: 1.15rem; }
  &__tagline { color: #9ca3af; font-size: 0.875rem; margin: 6px 0 0; }
  &__links { display: flex; gap: 32px; flex-wrap: wrap; justify-content: center; }
  &__link { color: #d1d5db; font-size: 0.875rem; transition: color 0.2s; &:hover { color: #fff; } }
  &__copy { color: #6b7280; font-size: 0.8rem; margin: 0; }
}

// ── Responsive ────────────────────────────────────────────────────────────────
@media (max-width: 1023px) {
  .vp__cards { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 767px) {
  .hero {
    padding: 60px 0 50px;
    &__inner { grid-template-columns: 1fr; gap: 40px; }
  }
  .token-graphic { padding: 24px 20px; gap: 10px; }
  .token { width: 70px; &__icon { width: 52px; height: 52px; font-size: 1.3rem; } }

  .hiw__steps { flex-direction: column; align-items: center; }
  .hiw__step { padding: 0; max-width: 320px; width: 100%; }
  .hiw__connector { width: 2px; height: 40px; background: linear-gradient(180deg, #6ee7b7, #059669); }

  .vp__cards { grid-template-columns: 1fr; }
}

// ═══════════════════════════ FEATURED TOKENS ═══════════════════════════
.featured-tokens {
  background: #f8fffe;
  padding: 64px 0;
  border-top: 1px solid #d1fae5;
  border-bottom: 1px solid #d1fae5;

  &__loading {
    text-align: center;
    color: #6b7280;
    padding: 40px 0;
  }

  &__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
    gap: 20px;
    margin-top: 32px;
  }

  &__empty {
    text-align: center;
    color: #6b7280;
    padding: 40px 0;
    grid-column: 1 / -1;
  }
}

.ft-card {
  background: #ffffff;
  border: 1px solid #d1fae5;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  display: flex;
  flex-direction: column;

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(5, 150, 105, 0.15);
    border-color: #059669;
  }

  &:focus-visible {
    outline: 3px solid #059669;
    outline-offset: 2px;
  }

  &__image {
    height: 140px;
    background: #f0fdf4;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;

    img {
      width: 100%;
      height: 100%;
      object-fit: cover;
    }
  }

  &__image-placeholder {
    font-size: 3rem;
    color: #a7f3d0;
  }

  &__body {
    padding: 16px 16px 8px;
    flex: 1;
  }

  &__company {
    font-size: 0.72rem;
    font-weight: 600;
    color: #059669;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 4px;
  }

  &__product {
    font-size: 1rem;
    font-weight: 700;
    color: #064e3b;
    margin-bottom: 10px;
    line-height: 1.3;
  }

  &__stats {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  &__stat {
    display: flex;
    flex-direction: column;
    font-size: 0.78rem;
    color: #374151;
  }

  &__stat-label {
    font-size: 0.68rem;
    color: #9ca3af;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  &__footer {
    padding: 10px 16px 14px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-top: 1px solid #f0fdf4;
  }

  &__price {
    font-size: 1rem;
    font-weight: 700;
    color: #059669;
  }

  &__cta {
    font-size: 0.78rem;
    font-weight: 600;
    color: #059669;
  }
}

