// ============================================
// User Theme (Company & Investor) - Light
// Professional blue/cyan palette with soft gray tint
// ============================================

@use '../variables' as *;
@use '../mixins' as *;

// Theme Colors
$user-primary-400: #22d3ee;  // Cyan
$user-primary-500: #06b6d4;
$user-primary-600: #0891b2;

$user-secondary-400: #60a5fa;  // Blue
$user-secondary-500: #3b82f6;
$user-secondary-600: #2563eb;

$user-accent-400: #34d399;  // Emerald
$user-accent-500: #10b981;
$user-accent-600: #059669;

// Background Colors - Light with blue tint
$user-bg-base: #f8fafc;        // Very light blue-gray
$user-bg-surface: #ffffff;      // White
$user-bg-elevated: #f0f9ff;     // Light sky blue
$user-bg-hover: #e0f2fe;        // Soft cyan hover

// Border Colors
$user-border-subtle: #e0f2fe;
$user-border-default: #bae6fd;
$user-border-strong: #7dd3fc;

// Text Colors - Dark for light theme
$user-text-primary: #0c4a6e;    // Deep sky blue
$user-text-secondary: #0369a1;  // Dark cyan
$user-text-muted: #64748b;      // Slate gray

// Gradient
$user-gradient-primary: linear-gradient(135deg, $user-primary-500 0%, $user-secondary-500 100%);
$user-gradient-accent: linear-gradient(135deg, $user-accent-500 0%, $user-primary-500 100%);

// ============================================

